# The issue: I need to check the result array for horizontal neighbors to propagate the change
# If any horizontal neighbor in RESULT is different from cell_val, change this cell

def change_adjacent_to_other_same_row(grid, cell_val, change_to):
    H, W = len(grid), len(grid[0])
    result = [r[:] for r in grid]

    for r in range(H):
        # First check if this row is solid (in result)
        if all(result[r][c] == cell_val for c in range(W)):
            continue
        # Row is mixed (has both cell_val and other colors in result)

        for c in range(W):
            if result[r][c] == cell_val:
                # Check horizontal neighbors in RESULT (already modified)
                if c > 0 and result[r][c-1] != cell_val:
                    result[r][c] = change_to
                elif c < W-1 and result[r][c+1] != cell_val:
                    result[r][c] = change_to

    return result

result3 = change_adjacent_to_other_same_row(demo_input, 2, 1)
print(f"Match: {result3 == demo_output}")
for i in range(len(demo_output)):
    for c in range(len(demo_output[i])):
        if result3[i][c] != demo_output[i][c]:
            print(f"Row {i}, Col {c}: Got {result3[i][c]}, Expected {demo_output[i][c]}")

print()
