def solution_v1(grid, change_to):
    H, W = len(grid), len(grid[0])
    result = [r[:] for r in grid]

    for r in range(H):
        row = grid[r]
        anchor1 = row[0]
        anchor2 = row[-1]

        if anchor1 == anchor2:
            # Same color at both ends: check if solid
            solid = all(row[c] == anchor1 for c in range(W))
            if solid:
                continue  # Keep solid

            # Not solid but anchor1 == anchor2: there must be an interior run
            col_first_not_anchor = -1
            for c in range(W):
                if row[c] != anchor1:
                    col_first_not_anchor = c
                    break

            col_last_not_anchor = -1
            for c in range(W-1, -1, -1):
                if row[c] != anchor1:
                    col_last_not_anchor = c
                    break

            # Change region between first and last non-anchor
            for c in range(col_first_not_anchor, col_last_not_anchor + 1):
                if row[c] != anchor1:
                    result[r][c] = change_to

        else:
            # Different colors at ends
            # Find where first color region ends
            first_anchor = anchor1
            first_anchor_end = -1
            for c in range(W):
                if row[c] == first_anchor:
                    first_anchor_end = c + 1 if c + 1 < W else W
                else:
                    break

            # Find where second color region starts (from right)
            second_anchor = anchor2
            second_anchor_start = -1
            for c in range(W-1, -1, -1):
                if row[c] == second_anchor:
                    second_anchor_start = c
                else:
                    break

            # Change cells in the region between (not including anchors)
            for c in range(first_anchor_end, second_anchor_start):
                if row[c] != first_anchor:
                    result[r][c] = change_to

    return result

