def solution_v2(grid, change_to):
    H, W = len(grid), len(grid[0])
    result = [r[:] for r in grid]

    for r in range(H):
        row = grid[r]
        anchor1 = row[0]
        anchor2 = row[-1]

        if anchor1 == anchor2:
            # Same color at both ends: check if solid
            solid = all(row[c] == anchor1 for c in range(W))
            if solid:
                continue  # Keep solid

            # Not solid but anchor1 == anchor2: interior run of non-anchor
            col_first_not_anchor = -1
            for c in range(W):
                if row[c] != anchor1:
                    col_first_not_anchor = c
                    break

            col_last_not_anchor = -1
            for c in range(W-1, -1, -1):
                if row[c] != anchor1:
                    col_last_not_anchor = c
                    break

            # Change region between first and last non-anchor
            for c in range(col_first_not_anchor, col_last_not_anchor + 1):
                if row[c] != anchor1:
                    result[r][c] = change_to

        else:
            # Different colors at ends
            # Find where first color (anchor1) region ends
            first_anchor_end = -1
            for c in range(W):
                if row[c] == anchor1:
                    first_anchor_end = c + 1 if c + 1 < W else W
                else:
                    break

            # Find region of second color (anchor2) on the right
            second_anchor_regions = []
            for c in range(W):
                if row[c] == anchor2:
                    # Found a region of anchor2
                    # Find its start
                    is_in_left_anchor_region = c < first_anchor_end
                    if not is_in_left_anchor_region:
                        second_anchor_regions.append(c)

            # Actually simpler: just check cell by cell
            # Cells in the "middle region" that are NOT anchor1 should be changed
            # Middle region is from first_anchor_end (exclusive) to last (W-1, inclusive)

            for c in range(first_anchor_end, W):
                if row[c] != anchor1 and row[c] != anchor2:
                    result[r][c] = change_to
                # But wait, this assumes all non-anchor1, non-anchor2 are in between

    return result

# Test v2
